/**
 * @deepseek-ai/dsh-tool-browser —— agent 可用的浏览器工具（iOS 原生 WKWebView）
 *
 * ## 背景
 *
 * DSH 自带的 `sidebar-browser` 是**纯 UI**：它 inject 只有
 * `['slots','locale','sidebarRight','sidebarRightTabs']`，不注册任何
 * `ctx.tools`。所以 agent 碰不到侧边栏浏览器，只能用 `web_search` /
 * `web_fetch`（纯 HTTP，拿不到 JS 渲染后的页面、不能点击输入）。
 *
 * 本插件补上这个缺口：把 iOS App 里的 `DSHBrowserBridge`（真实 WKWebView）
 * 暴露成一组 agent 工具。
 *
 * ## 架构
 *
 * ```
 *   agent  →  browser_open()  ──HTTP──▶  App 的 /browser 端点
 *                                            │
 *                                            ▼
 *                                     DSHBrowserBridge
 *                                            │
 *                                            ▼
 *                                    WKWebView（显示在用户眼前）
 * ```
 *
 * 走 HTTP 而不是 IPC，是因为 dsh 内核（node 进程）和 App（UIKit）是两个
 * 独立进程，中间只有 localhost 可用。
 *
 * ## 开关
 *
 * 默认关闭。开启方式：
 *   dsh-ctl browser on      # 写标记文件
 *   或在 App 菜单里点「允许 agent 操作浏览器」
 *
 * 工具注册用 `{ when }` 守卫，关闭时工具**不出现在工具列表里**，
 * 而不是出现后调用失败。
 *
 * ## 安全
 *
 * - 所有操作都在用户可见的 WKWebView 里，用户能实时看到
 * - 不开 headless 实例，不偷偷后台抓取
 * - `browser_eval` 限制在页面主世界，不能访问 App 的 bridge
 */

import { defineTool } from '@deepseek-ai/dsh-tools';
import { readFileSync, existsSync } from 'node:fs';
import { request } from 'node:http';

/** Cordis 插件名（loader 诊断用）。 */
export const name = 'tool-browser';

/** 依赖的服务。 */
export const inject = ['tools'];

/** 开关标记文件：存在则启用。 */
const ENABLE_FLAG = '/var/mobile/Media/deepseek-harness/config/browser-agent.enabled';

/** App 的 browser 控制端点（DSHBrowserBridge 监听）。 */
const CONTROL_HOST = '127.0.0.1';
const CONTROL_PORT = 3081;

/** 单次操作超时。 */
const DEFAULT_TIMEOUT_MS = 30000;

// ============================================================================
// 与 App 通信
// ============================================================================

/**
 * 调用 App 的 browser 控制端点。
 *
 * @param {string} action - open | snapshot | click | type | screenshot | eval
 * @param {object} payload - 动作参数
 * @param {AbortSignal} [signal] - 取消信号
 * @returns {Promise<object>} 端点返回的 JSON
 */
function callApp(action, payload, signal) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify({ action, ...payload });
    const req = request({
      host: CONTROL_HOST,
      port: CONTROL_PORT,
      path: '/browser',
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'content-length': Buffer.byteLength(body),
      },
      timeout: DEFAULT_TIMEOUT_MS,
    }, (res) => {
      let data = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        if (res.statusCode !== 200) {
          reject(new Error(`browser endpoint ${res.statusCode}: ${data.slice(0, 200)}`));
          return;
        }
        try {
          resolve(JSON.parse(data));
        } catch (e) {
          reject(new Error(`browser endpoint returned invalid JSON: ${data.slice(0, 200)}`));
        }
      });
    });

    req.on('error', (err) => {
      reject(new Error(
        `无法连接浏览器控制端点（${CONTROL_HOST}:${CONTROL_PORT}）。` +
        `请确认 App 正在运行。原始错误：${err.message}`
      ));
    });
    req.on('timeout', () => {
      req.destroy(new Error('browser operation timed out'));
    });
    if (signal) {
      signal.addEventListener('abort', () => {
        req.destroy(new Error('browser operation aborted'));
      }, { once: true });
    }

    req.write(body);
    req.end();
  });
}

// ============================================================================
// 工具定义
// ============================================================================

/** 检查 agent 浏览器权限是否开启。 */
function browserAgentEnabled() {
  try {
    return existsSync(ENABLE_FLAG);
  } catch {
    return false;
  }
}

export function apply(ctx) {
  // ---------------------------------------------------------------- open
  ctx.tools.register(defineTool({
    name: 'browser_open',
    description:
      'Open a URL in the visible in-app browser (a real WKWebView on this device). '
      + 'Unlike web_fetch, this renders JavaScript, keeps cookies and login state, '
      + 'and the user can see the page. Returns a tab id for follow-up calls.',
    parameters: {
      url: {
        type: 'string',
        required: true,
        description: 'The HTTP(S) URL to open.',
      },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          tabId: { type: 'string', required: true },
          url: { type: 'string', required: true },
          title: { type: 'string' },
        },
      },
      render: (_args, value) => [{
        type: 'text',
        text: `已在可见浏览器中打开 ${value.url}（标签 ${value.tabId}）`,
      }],
    },
    async execute(args, exec) {
      const r = await callApp('open', { url: args.url }, exec.signal);
      return { tabId: r.tabId, url: r.url ?? args.url, title: r.title };
    },
  }), { when: browserAgentEnabled });

  // ---------------------------------------------------------------- snapshot
  ctx.tools.register(defineTool({
    name: 'browser_snapshot',
    description:
      'Read the current page as text. Returns the rendered DOM text (after JavaScript), '
      + 'the page title, URL, and a list of interactive elements with selectors you can '
      + 'pass to browser_click / browser_type.',
    parameters: {
      tabId: {
        type: 'string',
        required: false,
        description: 'Tab id from browser_open. Omit to use the active tab.',
      },
      maxChars: {
        type: 'integer',
        required: false,
        description: 'Cap on returned text length. Default 20000.',
      },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          url: { type: 'string', required: true },
          title: { type: 'string' },
          text: { type: 'string', required: true },
          truncated: { type: 'boolean' },
          interactive: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              properties: {
                selector: { type: 'string', required: true },
                tag: { type: 'string', required: true },
                text: { type: 'string' },
                type: { type: 'string' },
              },
            },
          },
        },
      },
      render: (_args, value) => [{
        type: 'text',
        text: `# ${value.title ?? '(无标题)'}\n${value.url}\n\n${value.text.slice(0, 2000)}`
          + (value.truncated ? '\n… (已截断)' : ''),
      }],
    },
    async execute(args, exec) {
      return await callApp('snapshot', {
        tabId: args.tabId,
        maxChars: args.maxChars ?? 20000,
      }, exec.signal);
    },
  }), { when: browserAgentEnabled });

  // ---------------------------------------------------------------- click
  ctx.tools.register(defineTool({
    name: 'browser_click',
    description:
      'Click an element in the visible browser. Use a selector from browser_snapshot. '
      + 'Waits for the resulting navigation or DOM update before returning.',
    parameters: {
      selector: {
        type: 'string',
        required: true,
        description: 'CSS selector of the element to click.',
      },
      tabId: { type: 'string', required: false, description: 'Tab id. Omit for active tab.' },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          clicked: { type: 'boolean', required: true },
          url: { type: 'string' },
          title: { type: 'string' },
        },
      },
      render: (_args, value) => [{
        type: 'text',
        text: value.clicked
          ? `已点击，当前页面：${value.title ?? ''} ${value.url ?? ''}`
          : '未找到元素或点击失败',
      }],
    },
    async execute(args, exec) {
      return await callApp('click', { selector: args.selector, tabId: args.tabId }, exec.signal);
    },
  }), { when: browserAgentEnabled });

  // ---------------------------------------------------------------- type
  ctx.tools.register(defineTool({
    name: 'browser_type',
    description:
      'Type text into an input or textarea in the visible browser. '
      + 'Optionally submit the form afterward.',
    parameters: {
      selector: { type: 'string', required: true, description: 'CSS selector of the input.' },
      text: { type: 'string', required: true, description: 'Text to enter.' },
      submit: {
        type: 'boolean',
        required: false,
        description: 'Press Enter / submit the form after typing. Default false.',
      },
      tabId: { type: 'string', required: false, description: 'Tab id. Omit for active tab.' },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          typed: { type: 'boolean', required: true },
          url: { type: 'string' },
        },
      },
      render: (_args, value) => [{
        type: 'text',
        text: value.typed ? '已输入文本' : '未找到输入框或输入失败',
      }],
    },
    async execute(args, exec) {
      return await callApp('type', {
        selector: args.selector,
        text: args.text,
        submit: args.submit === true,
        tabId: args.tabId,
      }, exec.signal);
    },
  }), { when: browserAgentEnabled });

  // ---------------------------------------------------------------- screenshot
  ctx.tools.register(defineTool({
    name: 'browser_screenshot',
    description:
      'Capture the visible browser viewport as a PNG image (base64). '
      + 'Useful when the page content is hard to read as text.',
    parameters: {
      tabId: { type: 'string', required: false, description: 'Tab id. Omit for active tab.' },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          mediaType: { type: 'string', required: true },
          data: { type: 'string', required: true },
          width: { type: 'integer' },
          height: { type: 'integer' },
        },
      },
      render: (_args, value) => [{
        type: 'text',
        text: `截图 ${value.width ?? '?'}×${value.height ?? '?'} (${value.mediaType})`,
      }],
    },
    async execute(args, exec) {
      return await callApp('screenshot', { tabId: args.tabId }, exec.signal);
    },
  }), { when: browserAgentEnabled });

  // ---------------------------------------------------------------- eval
  ctx.tools.register(defineTool({
    name: 'browser_eval',
    description:
      'Evaluate a JavaScript expression in the page and return its JSON-serializable result. '
      + 'Runs in the page main world; cannot reach the native bridge. '
      + 'Use for reading structured data that snapshot flattens away.',
    parameters: {
      expression: {
        type: 'string',
        required: true,
        description: 'A JavaScript expression. The last value is returned.',
      },
      tabId: { type: 'string', required: false, description: 'Tab id. Omit for active tab.' },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          ok: { type: 'boolean', required: true },
          result: {},
          error: { type: 'string' },
        },
      },
      render: (_args, value) => [{
        type: 'text',
        text: value.ok
          ? `结果：${JSON.stringify(value.result).slice(0, 2000)}`
          : `执行失败：${value.error ?? '未知错误'}`,
      }],
    },
    async execute(args, exec) {
      return await callApp('eval', { expression: args.expression, tabId: args.tabId }, exec.signal);
    },
  }), { when: browserAgentEnabled });
}
